// ═══════════════════════════════════════════════════════════════════════════════
// TRADUZIONI.TSX — translation runtime / lookup / normalization.
// Large translation dictionaries were moved byte-for-byte in Phase 10 to
// ./i18n/translationData.ts. Public exports remain available from this module.
// ═══════════════════════════════════════════════════════════════════════════════

import { TRANSLATIONS, FAINANCE_UI_TRANSLATIONS, FAINANCE_I18N_PHRASES } from './i18n/translationData';
export * from './i18n/translationData';

function fainanceNormPhrase(value){
  return String(value||"")
    .replace(/�/g,"")
    .replace(/’|‘|’|‘|`/g,"'")
    .replace(/“|��|“|”/g,'"')
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g,"")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g," ")
    .replace(/\s+/g," ")
    .trim();
}

var fainanceTranslationCache={};

function repairFainanceEncoding(value){
  var raw=String(value==null?"":value);
  if(!/[ÃÂâðÄÅÈÎÏ]/.test(raw))return raw;
  try{
    var decoded=decodeURIComponent(escape(raw));
    if(decoded&&decoded!==raw&&decoded.indexOf("�")<0)return decoded;
  }catch(e){}
  return raw;
}

function fainanceCleanTranslation(value){
  if(value==null)return null;
  var out=repairFainanceEncoding(String(value));
  return out.indexOf("�")>=0?null:out;
}

// Mantiene le icone decorative coerenti con il testo sorgente.
// Le tabelle legacy contengono alcune chiavi equivalenti con e senza emoji:
// la ricerca normalizzata non deve quindi aggiungere un'icona a un testo che
// la UI mostra già separatamente, né ripetere due volte la stessa icona.
function fainanceIsIconBaseCodePoint(cp){
  return (cp>=0x1F000&&cp<=0x1FAFF)||
    (cp>=0x1FC00&&cp<=0x1FFFF)||
    (cp>=0x2190&&cp<=0x21FF)||
    (cp>=0x2300&&cp<=0x23FF)||
    (cp>=0x2500&&cp<=0x27BF)||
    (cp>=0x2B00&&cp<=0x2BFF)||
    cp===0x00A9||cp===0x00AE||cp===0x203C||cp===0x2049||
    cp===0x2122||cp===0x2139||cp===0x3030||cp===0x303D||
    cp===0x3297||cp===0x3299;
}
function fainanceCodePointSize(cp){return cp>0xFFFF?2:1;}
function fainanceReadLeadingIcon(value){
  var text=String(value==null?"":value);
  var i=0;
  while(i<text.length&&/\s/.test(text.charAt(i)))i++;
  var start=i;
  if(i>=text.length)return null;
  var cp=text.codePointAt(i);
  if(!fainanceIsIconBaseCodePoint(cp))return null;
  i+=fainanceCodePointSize(cp);
  // Le bandiere sono composte da due indicatori regionali.
  if(cp>=0x1F1E6&&cp<=0x1F1FF&&i<text.length){
    var flagCp=text.codePointAt(i);
    if(flagCp>=0x1F1E6&&flagCp<=0x1F1FF)i+=fainanceCodePointSize(flagCp);
  }
  function consumeModifiers(){
    while(i<text.length){
      var mod=text.codePointAt(i);
      if(mod===0xFE0E||mod===0xFE0F||mod===0x20E3||(mod>=0x1F3FB&&mod<=0x1F3FF)){i+=fainanceCodePointSize(mod);continue;}
      break;
    }
  }
  consumeModifiers();
  while(i<text.length&&text.codePointAt(i)===0x200D){
    var joinerSize=fainanceCodePointSize(0x200D);
    var nextIndex=i+joinerSize;
    if(nextIndex>=text.length)break;
    var joined=text.codePointAt(nextIndex);
    if(!fainanceIsIconBaseCodePoint(joined))break;
    i=nextIndex+fainanceCodePointSize(joined);
    consumeModifiers();
  }
  var end=i;
  while(i<text.length&&/\s/.test(text.charAt(i)))i++;
  return {icon:text.slice(start,end),start:start,end:end,after:i};
}
function fainanceComparableIcon(value){return String(value||"").replace(/[\uFE0E\uFE0F]/g,"");}
export function normalizeFainanceTranslatedIcons(source, translated){
  var sourceRaw=String(source==null?"":source);
  var outputRaw=String(translated==null?"":translated);
  if(!outputRaw)return outputRaw;
  var outputLeading=(outputRaw.match(/^\s*/)||[""])[0];
  var outputBody=outputRaw.slice(outputLeading.length);
  var sourceIcon=fainanceReadLeadingIcon(sourceRaw);
  var firstOutputIcon=fainanceReadLeadingIcon(outputBody);
  if(!firstOutputIcon)return outputRaw;
  if(!sourceIcon){
    // Il sorgente non contiene icone: elimina quelle introdotte soltanto
    // dall'alias di traduzione, perché il componente può mostrarle a parte.
    var cleanBody=outputBody;
    var added=fainanceReadLeadingIcon(cleanBody);
    while(added){cleanBody=cleanBody.slice(added.after);added=fainanceReadLeadingIcon(cleanBody);}
    return outputLeading+cleanBody;
  }
  var firstComparable=fainanceComparableIcon(firstOutputIcon.icon);
  var rest=outputBody.slice(firstOutputIcon.after);
  var duplicate=fainanceReadLeadingIcon(rest);
  var removed=false;
  while(duplicate&&fainanceComparableIcon(duplicate.icon)===firstComparable){
    rest=rest.slice(duplicate.after);
    duplicate=fainanceReadLeadingIcon(rest);
    removed=true;
  }
  if(!removed)return outputRaw;
  return outputLeading+outputBody.slice(0,firstOutputIcon.end)+(rest?" "+rest:"");
}

function buildFainanceTranslationLookup(code){
  var targetTable=TRANSLATIONS[code]||TRANSLATIONS.en||{};
  var exact={};
  var normalized={};
  function add(source,target){
    var cleanSource=fainanceCleanTranslation(source);
    var cleanTarget=fainanceCleanTranslation(target);
    if(!cleanSource||!cleanTarget)return;
    if(exact[cleanSource]===undefined)exact[cleanSource]=cleanTarget;
    var n=fainanceNormPhrase(cleanSource);
    if(n&&!normalized[n])normalized[n]=cleanTarget;
  }
  Object.keys(targetTable||{}).forEach(function(k){
    add(k,targetTable[k]);
    add(targetTable[k],targetTable[k]);
  });
  try{
    var italianTable=TRANSLATIONS.it||{};
    Object.keys(TRANSLATIONS||{}).forEach(function(langCode){
      var sourceTable=TRANSLATIONS[langCode]||{};
      Object.keys(sourceTable).forEach(function(k){
        var target=targetTable[k]||targetTable[italianTable[k]];
        if(typeof target==="string"){
          add(k,target);
          add(sourceTable[k],target);
        }
      });
    });
    Object.keys(italianTable).forEach(function(k){
      var target=targetTable[k]||targetTable[italianTable[k]];
      if(typeof target!=="string")return;
      Object.keys(TRANSLATIONS||{}).forEach(function(langCode){
        var sourceTable=TRANSLATIONS[langCode]||{};
        add(sourceTable[k],target);
        add(sourceTable[italianTable[k]],target);
      });
    });
  }catch(e){}
  var keys=Object.keys(exact||{}).filter(function(k){return k&&k.length>=4&&exact[k]&&exact[k]!==k;}).sort(function(a,b){return b.length-a.length;});
  return {exact:exact,normalized:normalized,keys:keys};
}

function getFainanceTranslationLookup(code){
  var safe=TRANSLATIONS[code]?code:"en";
  if(!fainanceTranslationCache[safe])fainanceTranslationCache[safe]=buildFainanceTranslationLookup(safe);
  return fainanceTranslationCache[safe];
}

function fainanceStripLegacyDistributionDash(value){
  var out=String(value==null?"":value);
  var trimmed=out.trim();
  if(!trimmed)return out;
  var clean=trimmed.replace(/(?:\s*[\-‐‑‒–—―−﹘﹣－]+\s*)+$/g,"").trim();
  if(clean===trimmed)return out;
  var canonical=[
    "Distribuzione uscite",
    "Distribuzione spese",
    "Expense distribution",
    "Distribution expense",
    "Distribución de gastos",
    "Répartition des dépenses",
    "Ausgabenverteilung",
    "Distribuição de despesas",
    "Rozkład wydatków",
    "Podział wydatków",
    "Uitgavenverdeling",
    "Distribuția cheltuielilor",
    "Κατανομή εξόδων"
  ];
  if(canonical.indexOf(clean)<0)return out;
  return out.replace(trimmed,clean);
}

export function translateFainanceText(value, lang){
  var raw=repairFainanceEncoding(String(value==null?"":value));
  var code=lang||"it";
  function finish(candidate){return fainanceStripLegacyDistributionDash(normalizeFainanceTranslatedIcons(raw,candidate));}
  if(!raw)return raw;
  if(code==="it")return fainanceStripLegacyDistributionDash(raw);
  var leading=(raw.match(/^\s*/)||[""])[0];
  var trailing=(raw.match(/\s*$/)||[""])[0];
  var text=raw.trim();
  if(!text)return raw;
  if(/^[\d\s.,:;€$%+\-()\/]+$/.test(text))return raw;
  var lookup=getFainanceTranslationLookup(code);
  if(lookup.exact[text]!==undefined)return finish(fainancePostProcessTranslation(leading+lookup.exact[text]+trailing, code));
  var wanted=fainanceNormPhrase(text);
  if(wanted&&lookup.normalized[wanted]!==undefined)return finish(fainancePostProcessTranslation(leading+lookup.normalized[wanted]+trailing, code));
  var pref=text.match(/^([^A-Za-zÀ-ÿ0-9]+\s*)([\s\S]+)$/);
  if(pref&&pref[2]&&pref[2]!==text){
    var sub=translateFainanceText(pref[2],code);
    if(sub!==pref[2])return finish(fainancePostProcessTranslation(leading+pref[1]+sub+trailing, code));
  }
  // 1.6.53: translate composed labels such as "Distribuzione uscite – Giugno",
  // "di € 2000,00" or mixed-language fragments produced by previous dictionaries.
  try{
    var keys=lookup.keys||[];
    for(var i=0;i<keys.length;i++){
      var k=keys[i];
      if(text===k)continue;
      var idx=text.indexOf(k);
      if(idx<0)continue;
      var before=idx===0?"":text[idx-1];
      var afterIdx=idx+k.length;
      var after=afterIdx>=text.length?"":text[afterIdx];
      var leftOk=!before||/[^A-Za-zÀ-ÿ0-9]/.test(before);
      var rightOk=!after||/[^A-Za-zÀ-ÿ0-9]/.test(after);
      if(!leftOk||!rightOk)continue;
      var replaced=text.slice(0,idx)+lookup.exact[k]+text.slice(afterIdx);
      if(replaced!==text){text=replaced;i=-1;continue;}
    }
    if(text!==raw.trim())return finish(fainancePostProcessTranslation(leading+text+trailing, code));
  }catch(e){}
  return finish(fainancePostProcessTranslation(raw, code));
}

// fAInance 1.6.54 - final post-processor for mixed-language leftovers and source-wide labels.
function fainancePostProcessTranslation(value, lang){
  var code=lang||"it";
  var out=repairFainanceEncoding(String(value==null?"":value));
  if(!out||code==="it")return out;
  function rep(a,b){out=out.replace(a,b);}
  if(code==="es"){
    var exact={
      "Controla aggiornamenti":"Buscar actualizaciones",
      "Controlla aggiornamenti":"Buscar actualizaciones",
      "Saldo ultimi 12 mesi":"Saldo últimos 12 meses",
      "Mese corrente":"Mes actual",
      "All years":"Todos los años",
      "All months":"Todos los meses",
      "Selecciona tutte":"Seleccionar todo",
      "Alertas di spesa":"Alertas de gasto",
      "Tipo de soglia":"Tipo de umbral",
      "Superación immediata":"Superación inmediata",
      "Notas di texto":"Notas de texto",
      "Dati inseriti dall’usuario":"Datos introducidos por el usuario",
      "Ipoteca / Alquiler":"Hipoteca / Alquiler",
      "Tarjeta de debi":"Tarjeta de débito",
      "Share appare perché è attiva la visualizzazione delle spese Share nello storico.":"Share aparece porque está activa la visualización de los gastos Share en el historial.",
      "Share appears because Share expenses are shown in history.":"Share aparece porque está activa la visualización de los gastos Share en el historial.",
      "Colore + Gasto":"Color",
      "Reference income":"Ingresos de referencia",
      "Planned saving":"Ahorro planificado",
      "Current month comparison":"Comparación del mes actual",
      "Actual saving":"Ahorro real",
      "Compared to plan":"Comparado con el plan",
      "Manual amount":"Importe manual",
      "New Share project":"Nuevo proyecto Share",
      "Project name":"Nombre del proyecto",
      "Project description (optional)":"Descripción del proyecto (opcional)",
      "Save project":"Guardar proyecto"
    };
    if(exact[out.trim()])return out.replace(out.trim(), exact[out.trim()]);
    rep(/\bdi\b/g,"de"); rep(/\bdell[’']/g,"del "); rep(/\bdell’/g,"del "); rep(/\bdella\b/g,"de la"); rep(/\bdelle\b/g,"de las"); rep(/\bdegli\b/g,"de los");
    rep(/\bsoglia\b/gi,"umbral"); rep(/\bsoglie\b/gi,"umbrales"); rep(/\butente\b/gi,"usuario"); rep(/\butenti\b/gi,"usuarios"); rep(/\bimmediata\b/gi,"inmediata"); rep(/\bimmediato\b/gi,"inmediato");
    rep(/\bspese\b/gi,"gastos"); rep(/\buscite\b/gi,"gastos"); rep(/\bentrate\b/gi,"ingresos"); rep(/\bappunti\b/gi,"notas"); rep(/\bnote\b/gi,"notas"); rep(/\bdati\b/gi,"datos"); rep(/\bvoce\b/gi,"elemento"); rep(/\bvoci\b/gi,"elementos");
    rep(/\bmodificata\b/gi,"modificada"); rep(/\bmodificato\b/gi,"modificado"); rep(/\beliminata\b/gi,"eliminada"); rep(/\beliminato\b/gi,"eliminado");
    rep(/\bseleziona\b/gi,"selecciona"); rep(/\btutte\b/gi,"todo"); rep(/\btutti\b/gi,"todos"); rep(/\bnessun\b/gi,"ningún"); rep(/\bnessuna\b/gi,"ninguna");
    rep(/\baggiornamenti\b/gi,"actualizaciones"); rep(/\baggiorna\b/gi,"actualizar"); rep(/\baggiungi\b/gi,"añadir"); rep(/\bNuova\b/g,"Nueva"); rep(/\bNuovo\b/g,"Nuevo");
    rep(/Anade/g,"Añade"); rep(/Anadir/g,"Añadir"); rep(/Mas/g,"Más"); rep(/Telefono/g,"Teléfono"); rep(/contrasena/g,"contraseña");
    rep(/Distribucion/g,"Distribución"); rep(/Analisis/g,"Análisis"); rep(/Categoria/g,"Categoría"); rep(/ categorias/g," categorías"); rep(/Informacion/g,"Información"); rep(/Configuracion/g,"Configuración");
    rep(/\bMese\b/g,"Mes"); rep(/\bAnno\b/g,"Año"); rep(/\bImporto\b/g,"Importe"); rep(/\bMetodo\b/g,"Método"); rep(/\bDescrizione\b/g,"Descripción");
    rep(/\bRisparmio\b/g,"Ahorro"); rep(/\brisparmio\b/g,"ahorro"); rep(/\bObiettivi\b/g,"Objetivos"); rep(/\bImpostazioni\b/g,"Ajustes");
  }
  if(code==="fr"){
    rep(/\bdi\b/g,"de"); rep(/\bdella\b/g,"de la"); rep(/\bdelle\b/g,"des"); rep(/\bdegli\b/g,"des"); rep(/\butente\b/gi,"utilisateur"); rep(/\butenti\b/gi,"utilisateurs");
    rep(/\bsoglia\b/gi,"seuil"); rep(/\bsoglie\b/gi,"seuils"); rep(/\bspese\b/gi,"dépenses"); rep(/\buscite\b/gi,"dépenses"); rep(/\bentrate\b/gi,"revenus");
    rep(/\bdati\b/gi,"données"); rep(/\bappunti\b/gi,"notes"); rep(/\bvoce\b/gi,"élément"); rep(/\bvoci\b/gi,"éléments"); rep(/\bimmediata\b/gi,"immédiate");
    rep(/\bMese\b/g,"Mois"); rep(/\bAnno\b/g,"Année"); rep(/\bImporto\b/g,"Montant"); rep(/\bMetodo\b/g,"Méthode"); rep(/\bDescrizione\b/g,"Description");
    rep(/Fevrier/g,"Février"); rep(/Aout/g,"Août"); rep(/Decembre/g,"Décembre"); rep(/Depenses/g,"Dépenses"); rep(/Recu/g,"Reçu"); rep(/Telephone/g,"Téléphone");
  }
  if(code==="en"){
    rep(/\bdi\b/g,"of"); rep(/\bsoglia\b/gi,"threshold"); rep(/\butente\b/gi,"user"); rep(/\bspese\b/gi,"expenses"); rep(/\buscite\b/gi,"expenses"); rep(/\bentrate\b/gi,"income");
    rep(/\bMese\b/g,"Month"); rep(/\bAnno\b/g,"Year"); rep(/\bImporto\b/g,"Amount"); rep(/\bMetodo\b/g,"Method"); rep(/\bDescrizione\b/g,"Description");
  }
  return out;
}

