  function add(src, vals){
    var sources=Array.isArray(src)?src:[src];
    langs.forEach(ensure);
    sources.forEach(function(source){
      langs.forEach(function(lang){
        var val=vals[lang];
        if(typeof val==='string'){
          TRANSLATIONS[lang][source]=val;
          FAINANCE_UI_TRANSLATIONS[lang][source]=val;
        }
      });
    });
  }
  function addAll(src,en,es,fr,de,pt,pl,nl,ro,el){ add(src,{en:en,es:es,fr:fr,de:de,pt:pt,pl:pl,nl:nl,ro:ro,el:el}); }

